	[701001] = {
		id = 701001,
		lastTime = 2000,
		talkContent = '你们在旅途中，听闻了一段古老的传说：很久很久以前，雷吉奇卡斯曾试图用龙之能量的结晶制作雷吉铎拉戈，但由于结晶不足，只制作出了它的头部。古代的人们害怕当雷吉铎拉戈的整个身体都被制作出来，他们的国家会遭受毁灭，因此决定将其封印到神殿的深处。'
	},
	[701101] = {
		id = 701101,
		lastTime = 2000,
		talkContent = '这段古老的故事深深地吸引了你们，你们决定前往封印雷吉铎拉戈的神殿遗迹一探究竟。神殿的大门上布满了灰色的按钮，看起来只有正确点亮按钮才能进入神殿。'
	},
	[701201] = {
		id = 701201,
		lastTime = 2000,
		talkContent = '打开神殿大门，迎接你们的是三个古老的遗迹守护者，而且看上去并不友善'
